function insRow2()
{
var description = new Array();
description[0] = "<tbody><tr><td><p><span class='b_aj'>Corte Constitucional</span></p><p>- Par&aacute;grafo declarado EXEQUIBLE, salvo la expresi&oacute;n tachada 'del diez por ciento (10%)' declarada INEXEQUIBLE por la Corte Constitucional mediante Sentencia <A href='c-395_2022.html#INICIO' >C-395-22</A> de 9 de noviembre de 2022, Magistrada Ponente Dra. Natalia &Aacute;ngel Cabo.</p><p><span class='i_aj'>'La norma demandada regula una materia en general reservada a la ley marco, en tanto clasifica como una actividad aseguradora, en los t&eacute;rminos previstos en los art&iacute;culos <A href='constitucion_politica_1991_pr004.html#150' >150</A>, numeral 19 literal d), y <A href='constitucion_politica_1991_pr006.html#189' >189</A> numeral 24 de la Constituci&oacute;n. Por ende, el Congreso en principio deb&iacute;a limitarse a expedir las &#8220;normas generales&#8221; del SOAT, y a se&ntilde;alar en ellas los objetivos, las pol&iacute;ticas, orientaciones y criterios generales. No obstante, como el asunto regulado tambi&eacute;n se vincula al derecho de tr&aacute;nsito, en el cual el Congreso tiene una reserva competencial especial (CP arts <A href='constitucion_politica_1991_pr004.html#150' >150</A> nums 23 y 25), la ley puede formular algunas precisiones a la pol&iacute;tica general e, inclusive, establecer reglas detalladas, con dos l&iacute;mites: (i) no puede regular exhaustivamente el asunto, y (ii) debe siempre dejarle al Ejecutivo el margen necesario para adaptar las disposiciones aplicables a las sucesivas coyunturas que se presenten en la realidad regulada. En este caso, en general, la ley se ajusta a esos l&iacute;mites, excepto por la fijaci&oacute;n de porcentajes espec&iacute;ficos en el descuento en la prima del SOAT y en los cargos por intermediaci&oacute;n en la venta de ese seguro, que vulneran la segunda de las restricciones mencionadas, por las razones anteriormente expuestas en esta providencia' </span></p> </td></tr></tbody>";
var z=document.getElementById('Table2').rows[0];
if (z==null) {
              var x=document.getElementById('Table2').insertRow(0)
              var y=x.insertCell(0)
              y.innerHTML=description
             }
else         {
              document.getElementById('Table2').deleteRow(0)
             }
}
