function insRow9()
{
var description = new Array();
description[0] = "<tbody><tr><td><p><span class='b_aj'>Texto original de la Ley 769 de 2002:</span></p><p>ART&Iacute;CULO 45. Los veh&iacute;culos automotores llevar&aacute;n dos (2) placas iguales: una en el extremo delantero y otra en el extremo trasero.</p><p>Los remolques, semirremolques y similares de transporte de carga tendr&aacute;n una placa conforme a las caracter&iacute;sticas que determine el Ministerio de Transporte. Las motocicletas, motociclos, mototriciclos y bicicletas llevar&aacute;n una sola placa reflectiva en el extremo trasero con base en las mismas caracter&iacute;sticas y seriado de las placas de los dem&aacute;s veh&iacute;culos.</p><p>Los veh&iacute;culos de tracci&oacute;n animal, agr&iacute;colas y montacargas, deber&aacute;n llevar una placa reflectiva en el extremo trasero como identificaci&oacute;n.</p><p>Ning&uacute;n veh&iacute;culo automotor matriculado en Colombia podr&aacute; llevar, en el lugar destinado a las placas, distintivos similares a &eacute;stas o que la imiten, ni que correspondan a placas de otros pa&iacute;ses, so pena de incurrir en la sanci&oacute;n prevista en este C&oacute;digo para quien transite sin placas; estas deben de estar libres de obst&aacute;culos que dificulten su plena identificaci&oacute;n.</p><p>PAR&Aacute;GRAFO. En caso de hurto o p&eacute;rdida de la placa, se expedir&aacute; el duplicado con el mismo n&uacute;mero.</p> </td></tr></tbody>";
var z=document.getElementById('Table9').rows[0];
if (z==null) {
              var x=document.getElementById('Table9').insertRow(0)
              var y=x.insertCell(0)
              y.innerHTML=description
             }
else         {
              document.getElementById('Table9').deleteRow(0)
             }
}
