function insRow39()
{
var description = new Array();
description[0] = "<tbody><tr><td><p><span class='b_aj'>Corte Constitucional</span></p><p>- Aparte subrayado declarado EXEQUIBLE por la Corte Constitucional mediante Sentencia <A href='c-177_2016.html#inicio' >C-177-16</A> de 13 de abril de 2016, Magistrado Ponente Dr. Jorge Ignacio Pretelt Chaljub.</p><p><span class='i_aj'>'El art&iacute;culo 59 de la Ley 769 de 2002, que contiene en su &uacute;ltimo inciso la expresi&oacute;n impugnada, no tiene el car&aacute;cter de norma sancionatoria. Es claro de la redacci&oacute;n de la misma, que la disposici&oacute;n no establece una conducta reprochable, ni especifica la sanci&oacute;n aplicable, ni siquiera identifica a un responsable, sino que su intenci&oacute;n es la de establecer una regla de conducta formadora de cultura ciudadana y destinada a propender por el ejercicio del deber de solidaridad frente a personas constitucionalmente protegidas.</span></p><p><span class='i_aj'>En tal sentido, se advierte que la intenci&oacute;n y el efecto de la norma no es ni podr&iacute;a ser el de restringir el derecho de circulaci&oacute;n o la autonom&iacute;a de estas personas cuando no cuenten con la compa&ntilde;&iacute;a de un mayor de 16 a&ntilde;os, sino justamente por el contrario, el de reiterar el deber de solidaridad de la sociedad frente a ellos, que es un principio constitucional propio del Estado Social de Derecho' </span></p> </td></tr></tbody>";
var z=document.getElementById('Table39').rows[0];
if (z==null) {
              var x=document.getElementById('Table39').insertRow(0)
              var y=x.insertCell(0)
              y.innerHTML=description
             }
else         {
              document.getElementById('Table39').deleteRow(0)
             }
}
